cd /workspace && python3 - <<'EOF'
import csv, io, json, random, sys
sys.path.insert(0, '.')
from src.csv_exporter import export_csv
from src.json_exporter import export_json
from src.exporter import export_rows
from src.dispatcher import export

# Original implementations (pre-refactor), kept only for parity testing.
def orig_csv(rows):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["id", "name"])
    for row in rows:
        clean = ["" if row.get(key) is None else str(row[key]) for key in ("id", "name")]
        writer.writerow(clean)
    return buffer.getvalue()

def orig_json(rows):
    clean = []
    for row in rows:
        clean.append({key: "" if row.get(key) is None else str(row[key]) for key in ("id", "name")})
    return json.dumps(clean, ensure_ascii=False, separators=(",", ":"))

rng = random.Random(0)
values = [None, "", "x", "a,b", 'q"uote', "line\nbreak", "héllo", 0, 1, -2, 3.5, True, False, [1,2], {"k": "v"}, "  pad  "]
keys = ["id", "name", "extra"]
cases = [[], [{ "id": None }, {}], [{"name": "only"}]]
for _ in range(5000):
    n = rng.randrange(6)
    case = []
    for _ in range(n):
        row = {}
        for k in keys:
            if rng.random() < 0.6:
                row[k] = rng.choice(values)
        case.append(row)
    cases.append(case)

for i, case in enumerate(cases):
    snapshot = json.dumps(case, default=repr, ensure_ascii=False)
    a, b = orig_csv(iter(case)), export_csv(iter(case))
    assert a == b, (i, case, a, b)
    a, b = orig_json(iter(case)), export_json(iter(case))
    assert a == b, (i, case, a, b)
    # shared entry point parity and dispatcher parity
    assert export_rows(iter(case), "csv") == b"".join([orig_csv(iter(case)).encode()]).decode()
    assert export(case, "csv") == orig_csv(iter(case))
    assert export(case, "json") == orig_json(iter(case))
    # inputs (as lists) not mutated
    assert json.dumps(case, default=repr, ensure_ascii=False) == snapshot
    for bad in ("xml", "", None, "CSV", "jsonl", 1, ("csv",)):
        for fn in (lambda: export_rows([], bad), lambda: export(case, bad)):
            try:
                fn()
            except ValueError as e:
                assert str(e) == "unsupported format"
            else:
                raise AssertionError("no ValueError for %r" % (bad,))
print("parity fuzz passed for", len(cases), "cases")
EOF

